// Search providers and direct portal lookups.
// Every URL the engine reports comes from one of these responses. Nothing is generated by a model.

export interface Candidate {
  url: string;
  title: string;
  snippet: string;
  thumbnail?: string; // image of the property seen in search results
  via: string; // "search:portals", "lookup:zillow", "images", ...
  addressText?: string; // address string returned by a portal lookup
}

export interface SearchQuery {
  label: string;
  kind: 'web' | 'images' | 'videos';
  phrases: string[]; // OR-ed quoted phrases
  extra?: string; // unquoted terms (city, state, zip)
  sites?: string[]; // restrict to these domains
  num?: number;
}

export interface SearchProvider {
  name: string;
  search(q: SearchQuery, signal?: AbortSignal): Promise<Candidate[]>;
}

export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;

export class ProviderError extends Error {
  constructor(public provider: string, public code: 'auth' | 'rate_limit' | 'upstream' | 'timeout' | 'network', message?: string) {
    super(message ?? code);
  }
}

function classify(provider: string, status: number): ProviderError {
  if (status === 401 || status === 403) return new ProviderError(provider, 'auth', `HTTP ${status}`);
  if (status === 429) return new ProviderError(provider, 'rate_limit', 'HTTP 429');
  return new ProviderError(provider, 'upstream', `HTTP ${status}`);
}

export function renderGoogleQuery(q: SearchQuery): string {
  const phrases = q.phrases.map((p) => `"${p}"`);
  let s = phrases.length > 1 ? `(${phrases.join(' OR ')})` : phrases[0] ?? '';
  if (q.extra) s += ` ${q.extra}`;
  if (q.sites?.length) s += q.sites.length === 1 ? ` site:${q.sites[0]}` : ` (${q.sites.map((d) => `site:${d}`).join(' OR ')})`;
  return s.trim();
}

/**
 * Simpler forms of a query for search accounts that reject advanced operators
 * (Serper's free tier answers "Query pattern not allowed for free accounts").
 * Level 1 drops site: and OR, keeping one quoted phrase. Level 2 also drops the quotes.
 * Results are still verified by strict address matching, so simpler queries only cost recall.
 */
// Plain words that steer each simplified search toward the sites its full version targeted.
const PLAIN_HINTS: Record<string, string> = {
  portals: 'home for sale', brokerages: 'realtor listing', tours: 'virtual tour', video_social: 'video',
  rentals: 'for rent', media_words: 'photos', zip: 'listing',
};
// Use the other spelling of the street ("Dr" vs "Drive") for some, so the simplified searches don't all repeat.
const ALT_PHRASE = new Set(['zip', 'brokerages', 'tours']);

export function simplifyQuery(q: SearchQuery, level: number): string {
  if (level <= 0) return renderGoogleQuery(q);
  const phrase = (ALT_PHRASE.has(q.label) ? q.phrases[1] : undefined) ?? q.phrases[0] ?? '';
  const main = level === 1 ? `"${phrase}"` : phrase;
  const extra = (q.extra ?? '').split('(')[0].replace(/"/g, '').trim(); // drop any OR group
  return `${main} ${extra} ${PLAIN_HINTS[q.label] ?? ''}`.replace(/\s+/g, ' ').trim();
}

// Serper allows 5 requests per second per account. Space calls out across every scan running in this instance.
let nextSlot = 0;
const SERPER_GAP_MS = 250;
async function serperSlot(): Promise<void> {
  const now = Date.now();
  const at = Math.max(now, nextSlot);
  nextSlot = at + SERPER_GAP_MS;
  if (at > now) await new Promise((r) => setTimeout(r, at - now));
}

const RESTRICTED = /not allowed for free accounts|query pattern not allowed/i;

/** Serper.dev: Google results. https://serper.dev */
export function serperProvider(apiKey: string, fetchFn: FetchLike = fetch): SearchProvider {
  // Shared across queries in this scan: once a pattern is refused, use the simpler form from then on,
  // and don't pay twice for queries that collapse to the same text.
  let level = 0;
  const seen = new Map<string, Promise<any>>();
  async function call(endpoint: string, text: string, num: number, signal?: AbortSignal, attempt = 0): Promise<any> {
    let res: Response;
    await serperSlot();
    try {
      res = await fetchFn(`https://google.serper.dev/${endpoint}`, {
        method: 'POST',
        headers: { 'X-API-KEY': apiKey, 'Content-Type': 'application/json' },
        body: JSON.stringify({ q: text, num, gl: 'us', hl: 'en' }),
        signal,
      });
    } catch (e) {
      throw new ProviderError('serper', (e as Error).name === 'AbortError' ? 'timeout' : 'network');
    }
    if (res.status === 429 && attempt < 2) {
      await new Promise((r) => setTimeout(r, 1000 * (attempt + 1)));
      return call(endpoint, text, num, signal, attempt + 1);
    }
    if (!res.ok) {
      const err = classify('serper', res.status);
      // Keep Serper's own reason (e.g. invalid key, out of credits) for diagnostics. It never contains the key.
      err.message = `HTTP ${res.status} ${(await res.text().catch(() => '')).slice(0, 160)}`.trim();
      throw err;
    }
    return res.json();
  }
  return {
    name: 'serper',
    async search(q, signal) {
      const endpoint = q.kind === 'images' ? 'images' : q.kind === 'videos' ? 'videos' : 'search';
      let data: any;
      for (;;) {
        const text = simplifyQuery(q, level);
        const key = `${endpoint}|${text}`;
        let p = seen.get(key);
        if (!p) {
          p = call(endpoint, text, level > 0 ? 10 : q.num ?? 20, signal);
          seen.set(key, p);
        }
        try {
          data = await p;
          break;
        } catch (e) {
          if (e instanceof ProviderError && RESTRICTED.test(e.message) && level < 2) {
            level = Math.max(level, simplifyQuery(q, level) === text ? level + 1 : level);
            continue;
          }
          throw e;
        }
      }
      if (q.kind === 'images') {
        return (data.images ?? []).map((r: Record<string, string>) => ({
          url: r.link, title: r.title ?? '', snippet: '', thumbnail: r.thumbnailUrl ?? r.imageUrl, via: `images:${q.label}`,
        }));
      }
      if (q.kind === 'videos') {
        return (data.videos ?? []).map((r: Record<string, string>) => ({
          url: r.link, title: r.title ?? '', snippet: r.snippet ?? '', thumbnail: r.imageUrl, via: `videos:${q.label}`,
        }));
      }
      return (data.organic ?? []).map((r: Record<string, unknown>) => ({
        url: r.link as string, title: (r.title as string) ?? '', snippet: (r.snippet as string) ?? '',
        thumbnail: (r.imageUrl as string) ?? undefined, via: `search:${q.label}`,
      }));
    },
  };
}

/** Brave Search API. https://brave.com/search/api — site groups are searched one site at a time. */
export function braveProvider(apiKey: string, fetchFn: FetchLike = fetch): SearchProvider {
  const one = async (query: string, kind: SearchQuery['kind'], label: string, signal?: AbortSignal): Promise<Candidate[]> => {
    const path = kind === 'images' ? 'images/search' : kind === 'videos' ? 'videos/search' : 'web/search';
    let res: Response;
    try {
      res = await fetchFn(`https://api.search.brave.com/res/v1/${path}?q=${encodeURIComponent(query)}&count=20&country=us`, {
        headers: { 'X-Subscription-Token': apiKey, Accept: 'application/json' },
        signal,
      });
    } catch (e) {
      throw new ProviderError('brave', (e as Error).name === 'AbortError' ? 'timeout' : 'network');
    }
    if (!res.ok) throw classify('brave', res.status);
    const data = await res.json();
    const rows = kind === 'web' ? data.web?.results ?? [] : data.results ?? [];
    return rows.map((r: Record<string, any>) => ({
      url: r.url, title: r.title ?? '', snippet: r.description ?? '',
      thumbnail: r.thumbnail?.src ?? r.properties?.url, via: `${kind === 'web' ? 'search' : kind}:${label}`,
    }));
  };
  return {
    name: 'brave',
    async search(q, signal) {
      const base = renderGoogleQuery({ ...q, sites: undefined });
      if (!q.sites?.length) return one(base, q.kind, q.label, signal);
      const out: Candidate[] = [];
      for (const d of q.sites.slice(0, 4)) out.push(...(await one(`${base} site:${d}`, q.kind, q.label, signal)));
      return out;
    },
  };
}

// ─── Direct portal lookups ────────────────────────────────────────────────
// The 10-address test (Nov 2026) found that the portals' own address autocomplete returns the exact
// property page for 10 of 10 homes, while web search never surfaced the exact Zillow page.

const BROWSER_HEADERS = {
  'User-Agent': 'Mozilla/5.0 (Macintosh; Intel Mac OS X 14_6) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0 Safari/537.36',
  Accept: 'application/json, text/plain, */*',
  'Accept-Language': 'en-US,en;q=0.9',
};

export interface PortalLookup {
  key: string;
  run(addressLine: string, fetchFn: FetchLike, signal?: AbortSignal): Promise<Candidate[]>;
}

export const zillowLookup: PortalLookup = {
  key: 'zillow',
  async run(addressLine, fetchFn, signal) {
    const url = `https://www.zillowstatic.com/autocomplete/v3/suggestions?q=${encodeURIComponent(addressLine)}&resultTypes=allAddress&resultCount=5`;
    const res = await fetchFn(url, { headers: BROWSER_HEADERS, signal });
    if (!res.ok) throw classify('zillow', res.status);
    const data = await res.json();
    const out: Candidate[] = [];
    for (const r of data.results ?? []) {
      const m = r.metaData ?? {};
      if (!m.zpid) continue;
      const text = [r.display, m.streetNumber, m.streetName, m.unitNumber ? `# ${m.unitNumber}` : '', m.city, m.state, m.zipCode].filter(Boolean).join(' ');
      out.push({
        url: `https://www.zillow.com/homedetails/${m.zpid}_zpid/`,
        title: r.display ?? '',
        snippet: '',
        via: 'lookup:zillow',
        addressText: text,
      });
    }
    return out;
  },
};

export const redfinLookup: PortalLookup = {
  key: 'redfin',
  async run(addressLine, fetchFn, signal) {
    const url = `https://www.redfin.com/stingray/do/location-autocomplete?location=${encodeURIComponent(addressLine)}&v=2`;
    const res = await fetchFn(url, { headers: BROWSER_HEADERS, signal });
    if (!res.ok) throw classify('redfin', res.status);
    const raw = await res.text();
    const data = JSON.parse(raw.replace(/^\{\}&&/, ''));
    const rows: Record<string, string>[] = [];
    if (data.payload?.exactMatch) rows.push(data.payload.exactMatch);
    for (const s of data.payload?.sections ?? []) for (const r of s.rows ?? []) rows.push(r);
    const seen = new Set<string>();
    const out: Candidate[] = [];
    for (const r of rows) {
      if (!r.url || !/\/home\/\d+/.test(r.url) || seen.has(r.url)) continue;
      seen.add(r.url);
      out.push({
        url: `https://www.redfin.com${r.url}`,
        title: [r.name, r.subName].filter(Boolean).join(', '),
        snippet: '',
        via: 'lookup:redfin',
        addressText: [r.name, r.subName, r.url.replace(/[-/]/g, ' ')].filter(Boolean).join(' '),
      });
    }
    return out;
  },
};

export const PORTAL_LOOKUPS: PortalLookup[] = [zillowLookup, redfinLookup];

/** Offline provider for demo mode and tests: returns canned results keyed by query label. */
export function fixtureProvider(results: Record<string, Candidate[]>): SearchProvider {
  return {
    name: 'fixture',
    async search(q) {
      return (results[q.label] ?? []).map((c) => ({ ...c, via: `${q.kind === 'web' ? 'search' : q.kind}:${q.label}` }));
    },
  };
}
